import { useState, useEffect, lazy, Suspense } from "react";
import BottomNav from "./components/layout/BottomNav";
import HomeScreen from "./screens/HomeScreen";
import MyReportsScreen from "./screens/MyReportsScreen";
import ProfileScreen from "./screens/ProfileScreen";
import EmergencyScreen from "./screens/EmergencyScreen";
import ReportModal from "./components/ui/ReportModal";

// Lazy-load the map — only initialises Mapbox GL when user first taps "Maps"
const MapScreen = lazy(() => import("./screens/MapScreen"));

import { supabase } from "./lib/supabase";

const GREEN = "#2d8119";
function Toast({ message, onDone }) {
  useEffect(() => {
    const t = setTimeout(onDone, 3000);
    return () => clearTimeout(t);
  }, [onDone]);
  return <div className="toast">{message}</div>;
}

import { motion, AnimatePresence } from "framer-motion";

function App() {
  const [activeScreen, setActiveScreen] = useState("home");
  const [modalOpen, setModalOpen] = useState(false);
  const [toast, setToast] = useState(null);
  const [userReports, setUserReports] = useState([]);
  const [mapVisited, setMapVisited] = useState(false);
  const [userLocation, setUserLocation] = useState(null);
  const [isLoadingReports, setIsLoadingReports] = useState(true);
  const [isMapFullView, setIsMapFullView] = useState(false);
  const [isNavMinimized, setIsNavMinimized] = useState(false);

  // ... (rest of the logic remains the same)

  // Fetch reports from Supabase on mount
  useEffect(() => {
    const fetchReports = async () => {
      try {
        const { data, error } = await supabase
          .from("reports")
          .select("*")
          .order("created_at", { ascending: false });

        if (error) throw error;

        // Transform the DB format to the local format if needed. Here we keep it similar.
        const formatted = data.map((r) => ({
          ...r,
          id: r.id,
          createdAt: r.created_at,
          statusLabel: r.status_label,
          photoPreview: r.photo_url || null,
        }));
        setUserReports(formatted);
      } catch (err) {
        console.error("Error fetching reports:", err);
      } finally {
        setIsLoadingReports(false);
      }
    };

    fetchReports();
  }, []);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) =>
          setUserLocation({
            lat: pos.coords.latitude,
            lng: pos.coords.longitude,
          }),
        (err) => console.log(err),
        { enableHighAccuracy: false, timeout: 5000, maximumAge: 10000 },
      );
      navigator.geolocation.watchPosition(
        (pos) =>
          setUserLocation({
            lat: pos.coords.latitude,
            lng: pos.coords.longitude,
          }),
        (err) => { },
        { enableHighAccuracy: false, timeout: 5000, maximumAge: 10000 },
      );
    }
  }, []);

  useEffect(() => {
    if (activeScreen === "home" && !mapVisited) setMapVisited(true);
    // Reset map full view when switching screens to avoid disappearing UI
    if (activeScreen !== "home") {
      setIsMapFullView(false);
    }
  }, [activeScreen, mapVisited]);

  const openModal = () => setModalOpen(true);
  const closeModal = () => setModalOpen(false);

  const handleSubmit = (newReport) => {
    setUserReports((prev) => [newReport, ...prev]);
  };

  const screenVariants = {
    initial: { opacity: 0, x: 20, scale: 0.98 },
    animate: { opacity: 1, x: 0, scale: 1 },
    exit: { opacity: 0, x: -20, scale: 0.98 },
    transition: { duration: 0.4, ease: [0.32, 0.72, 0, 1] }
  };

  return (
    <div className="app-shell">
      {/* SCREENS LAYER */}
      <AnimatePresence mode="wait">
        {activeScreen === "home" && (
          <motion.div
            key="home"
            variants={screenVariants}
            initial="initial"
            animate="animate"
            exit="exit"
            transition={screenVariants.transition}
            className="screen active"
            style={{ zIndex: 10, pointerEvents: "none" }}
          >
            <HomeScreen
              onOpenModal={openModal}
              userReports={userReports}
              isMapFullView={isMapFullView}
            />
          </motion.div>
        )}

        {activeScreen === "emergency" && (
          <motion.div
            key="emergency"
            variants={screenVariants}
            initial="initial"
            animate="animate"
            exit="exit"
            transition={screenVariants.transition}
            className="screen active"
            style={{ zIndex: 10, background: "#dae5d3" }}
          >
            <EmergencyScreen />
          </motion.div>
        )}

        {activeScreen === "mine" && (
          <motion.div
            key="mine"
            variants={screenVariants}
            initial="initial"
            animate="animate"
            exit="exit"
            transition={screenVariants.transition}
            className="screen active"
            style={{ zIndex: 10, background: "#dae5d3" }}
          >
            <MyReportsScreen onOpenModal={openModal} userReports={userReports} />
          </motion.div>
        )}

        {activeScreen === "profile" && (
          <motion.div
            key="profile"
            variants={screenVariants}
            initial="initial"
            animate="animate"
            exit="exit"
            transition={screenVariants.transition}
            className="screen active"
            style={{ zIndex: 10, background: "#dae5d3" }}
          >
            <ProfileScreen />
          </motion.div>
        )}
      </AnimatePresence>

      {/* MAP — Background layer */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          zIndex: 1,
          opacity: activeScreen === "home" ? 1 : 0,
          pointerEvents: activeScreen === "home" ? "auto" : "none",
          transition: "opacity 0.4s ease",
        }}
      >
        <Suspense
          fallback={
            <div
              className="map-loading"
              style={{ position: "relative", flex: 1 }}
            >
              <div style={{ fontSize: 34, marginBottom: 6 }}>🗺️</div>
              <div className="map-loading-text">Nilo-load ang mapa...</div>
            </div>
          }
        >
          <MapScreen
            onOpenModal={openModal}
            userReports={userReports}
            showMapUI={activeScreen === "home"}
            userLocation={userLocation}
            isMapFullView={isMapFullView}
            onMapDoubleClick={() => setIsMapFullView((prev) => !prev)}
            isNavMinimized={isNavMinimized}
          />
        </Suspense>
      </div>

      <BottomNav
        activeScreen={activeScreen}
        setActiveScreen={setActiveScreen}
        isHidden={activeScreen === "home" && isMapFullView}
        isMinimized={isNavMinimized}
        setIsMinimized={setIsNavMinimized}
        onFabClick={openModal}
      />

      {/* MODAL */}
      <ReportModal
        isOpen={modalOpen}
        onClose={closeModal}
        onSubmit={handleSubmit}
      />

      {/* TOAST */}
      {toast && <Toast message={toast} onDone={() => setToast(null)} />}
    </div>
  );
}

export default App;

import { Home, AlertTriangle, ClipboardList, User, Plus } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

const NAV_ITEMS = [
  { id: "home", Icon: Home, label: "Home" },
  { id: "emergency", Icon: AlertTriangle, label: "Emergency" },
  { id: "mine", Icon: ClipboardList, label: "My Reports" },
  { id: "profile", Icon: User, label: "Profile" },
];

export default function BottomNav({ activeScreen, setActiveScreen, isHidden, isMinimized, setIsMinimized, onFabClick }) {
  const activeItem = NAV_ITEMS.find(item => item.id === activeScreen) || NAV_ITEMS[0];
  const ActiveIcon = activeItem.Icon;

  return (
    <motion.nav
      initial={false}
      animate={{
        y: 0,
        scale: 1,
        width: isHidden ? 64 : (isMinimized ? 64 : "calc(100% - 28px)"),
        borderRadius: 28, // Consistent squircle shape for both modes
      }}
      transition={{
        duration: 0.7,
        ease: [0.32, 0.72, 0, 1]
      }}
      onClick={() => {
        if (isHidden && onFabClick) {
          onFabClick();
        }
      }}
      style={{
        position: "absolute",
        bottom: 0,
        right: 14,
        zIndex: 1000,
        marginBottom: "calc(16px + env(safe-area-inset-bottom, 0px))",
        height: 64,

        // Appearance
        background: "rgba(74, 94, 54, 0.95)",
        backdropFilter: "blur(12px)",
        WebkitBackdropFilter: "blur(12px)",
        border: "1px solid rgba(255,255,255,0.05)",
        boxShadow: isHidden ? "0 4px 20px rgba(74, 94, 54, 0.5)" : "0 4px 24px rgba(0, 0, 0, 0.15)",

        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
        pointerEvents: "auto",
        cursor: isHidden ? "pointer" : "default",
      }}
    >
      {/* FAB PLUS ICON CONTENT */}
      <AnimatePresence>
        {isHidden && (
          <motion.div
            key="fab-content"
            initial={{ opacity: 0, scale: 0.5, rotate: -45 }}
            animate={{ opacity: 1, scale: 1, rotate: 0 }}
            exit={{
              opacity: 0,
              scale: 0.8,
              rotate: 15,
              transition: { duration: 0.15, delay: 0 }
            }}
            transition={{ duration: 0.3, delay: 0.35 }}
            style={{
              position: "absolute",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              color: "white"
            }}
          >
            <Plus size={26} strokeWidth={2.5} />
          </motion.div>
        )}
      </AnimatePresence>

      {/* Minimized Icon Button */}
      {!isHidden && (
        <div
          onClick={() => setIsMinimized(false)}
          style={{
            position: "absolute",
            right: 0,
            width: 64,
            height: 64,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            opacity: isMinimized ? 1 : 0,
            pointerEvents: isMinimized ? "auto" : "none",
            transition: "opacity 0.3s ease",
            transitionDelay: isMinimized ? "0.2s" : "0s",
            cursor: "pointer",
            color: "white",
          }}
        >
          <div style={{ display: "flex", alignItems: "center", justifyContent: "center", paddingLeft: 2.6, paddingBottom: 1.5 }}>
            <ActiveIcon size={24} strokeWidth={2.2} />
          </div>
        </div>
      )}

      {/* Expanded Nav Items */}
      {!isHidden && (
        <div
          style={{
            display: "flex",
            width: "100%",
            height: "100%",
            opacity: isMinimized ? 0 : 1,
            pointerEvents: isMinimized ? "none" : "auto",
            transition: "opacity 0.2s ease",
            transitionDelay: isMinimized ? "0s" : "0.2s",
            position: "absolute",
            right: 0,
          }}
        >
          {NAV_ITEMS.map(({ id, Icon, label }) => {
            const isActive = activeScreen === id;
            return (
              <button
                key={id}
                onClick={() => {
                  setActiveScreen(id);
                  setIsMinimized(true);
                }}
                aria-label={label}
                style={{
                  flex: 1,
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 2,
                  padding: "8px 4px",
                  background: "none",
                  border: "none",
                  cursor: "pointer",
                  borderRadius: 28,
                  transition: "opacity 0.15s",
                  whiteSpace: "nowrap",
                }}
              >
                <div
                  style={{
                    width: 34,
                    height: 34,
                    background: "transparent",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    transition: "background 0.2s",
                  }}
                >
                  <Icon
                    size={22}
                    color={isActive ? "#ffffff" : "rgba(255,255,255,0.7)"}
                    strokeWidth={isActive ? 2.2 : 1.8}
                  />
                </div>
                <span
                  style={{
                    fontSize: 9,
                    fontWeight: isActive ? 800 : 700,
                    color: isActive ? "#ffffff" : "rgba(255,255,255,0.7)",
                    fontFamily: "Nunito, sans-serif",
                    letterSpacing: 0.2,
                  }}
                >
                  {label}
                </span>
              </button>
            );
          })}
        </div>
      )}
    </motion.nav>
  );
}

import { AnimatePresence, motion } from "framer-motion";
import { MapPin, ChevronDown } from "lucide-react";
import SearchBar from "./SearchBar";

export function MapOverlayActions({
  isMapFullView,
  mapMode,
  onOpenModal,
  activeFilters,
  setActiveFilters,
  filterOpen,
  setFilterOpen,
  setSearchPin,
  userLocation,
  mapRef,
}) {
  return (
    <div
      style={{
        position: "absolute",
        top: "calc(32px + env(safe-area-inset-top, 0px))",
        left: 16,
        right: 16,
        zIndex: 10,
        opacity: isMapFullView ? 1 : 0,
        pointerEvents: isMapFullView ? "auto" : "none",
        transform: isMapFullView ? "translateY(0)" : "translateY(-20px)",
        transition: "all 0.4s cubic-bezier(0.32, 0.72, 0, 1)",
      }}
    >
      <AnimatePresence>
        {mapMode === "report" ? (
          <motion.div
            key="report-mode"
            initial={{ opacity: 0, scale: 0.98, filter: "blur(4px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            exit={{ opacity: 0, scale: 0.98, filter: "blur(4px)" }}
            transition={{ duration: 0.7, ease: [0.32, 0.72, 0, 1] }}
            style={{
              display: "flex",
              gap: 10,
              alignItems: "stretch",
              width: "100%",
            }}
          >
            {/* Left Side: Mag-Sumbong */}
            <button
              onClick={onOpenModal}
              style={{
                flex: 2.5,
                background: "rgba(74, 94, 54, 0.95)",
                borderRadius: 40,
                padding: "10px 14px",
                display: "flex",
                alignItems: "center",
                gap: 12,
                border: "1px solid rgba(255,255,255,0.08)",
                boxShadow: "0 6px 20px rgba(0,0,0,0.2)",
                cursor: "pointer",
                textAlign: "left",
              }}
            >
              <div
                style={{
                  width: 40,
                  height: 40,
                  background: "white",
                  borderRadius: "50%",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  flexShrink: 0,
                  position: "relative",
                }}
              >
                <MapPin size={22} color="#4A5E36" />
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: 11,
                    fontWeight: 900,
                    color: "#4A5E36",
                    marginTop: -2,
                  }}
                >
                  !
                </div>
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div
                  style={{
                    color: "white",
                    fontWeight: 800,
                    fontSize: 13,
                    lineHeight: 1.2,
                  }}
                >
                  Mag-Sumbong
                </div>
                <div
                  style={{
                    color: "rgba(255,255,255,0.75)",
                    fontSize: 9,
                    fontWeight: 600,
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                  }}
                >
                  Report problems within Palayan City community
                </div>
              </div>
              <ChevronDown
                size={18}
                color="white"
                style={{
                  transform: "rotate(-90deg)",
                  flexShrink: 0,
                  opacity: 0.8,
                }}
              />
            </button>

            {/* Right Side: Recent Reports */}
            <button
              style={{
                flex: 1,
                background: "rgba(74, 94, 54, 0.95)",
                borderRadius: 40,
                padding: "10px 18px",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: 8,
                border: "1px solid rgba(255,255,255,0.08)",
                boxShadow: "0 6px 20px rgba(0,0,0,0.2)",
                cursor: "pointer",
                whiteSpace: "nowrap",
              }}
            >
              <div style={{ color: "white", fontWeight: 800, fontSize: 13 }}>
                Recent Reports
              </div>
              <ChevronDown
                size={16}
                color="white"
                style={{ flexShrink: 0, opacity: 0.8 }}
              />
            </button>
          </motion.div>
        ) : (
          <motion.div
            key="search-mode"
            initial={{ opacity: 0, scale: 0.98, filter: "blur(4px)" }}
            animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
            exit={{ opacity: 0, scale: 0.98, filter: "blur(4px)" }}
            transition={{ duration: 0.7, ease: [0.32, 0.72, 0, 1] }}
            style={{
              display: "flex",
              gap: 10,
              alignItems: "stretch",
              width: "100%",
              position: "absolute",
              top: 0,
              left: 0,
            }}
          >
            {/* Left Side: Search Bar */}
            <div style={{ flex: 2.5 }}>
              <SearchBar
                mapRef={mapRef}
                onSearchSelect={setSearchPin}
                userLocation={userLocation}
                isPill={true}
              />
            </div>

            {/* Right Side: Status Filter */}
            <div style={{ flex: 1, position: "relative" }}>
              <button
                onClick={() => setFilterOpen((v) => !v)}
                style={{
                  width: "100%",
                  height: "100%",
                  background: "rgba(74, 94, 54, 0.95)",
                  borderRadius: 40,
                  padding: "0 14px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 8,
                  border: "1px solid rgba(255,255,255,0.08)",
                  boxShadow: "0 6px 20px rgba(0,0,0,0.2)",
                  cursor: "pointer",
                  paddingTop: 14,
                  paddingBottom: 14,
                }}
              >
                <div style={{ display: "flex", gap: 5, flexShrink: 0 }}>
                  {activeFilters.includes("pending") && (
                    <div
                      style={{
                        width: 8,
                        height: 8,
                        borderRadius: "50%",
                        background: "#ff8c8c",
                      }}
                    />
                  )}
                  {activeFilters.includes("inprogress") && (
                    <div
                      style={{
                        width: 8,
                        height: 8,
                        borderRadius: "50%",
                        background: "#80bfff",
                      }}
                    />
                  )}
                  {activeFilters.includes("resolved") && (
                    <div
                      style={{
                        width: 8,
                        height: 8,
                        borderRadius: "50%",
                        background: "#8ce68c",
                      }}
                    />
                  )}
                </div>
                <ChevronDown
                  size={14}
                  color="white"
                  style={{
                    flexShrink: 0,
                    opacity: 0.7,
                    transform: filterOpen ? "rotate(180deg)" : "rotate(0deg)",
                    transition: "transform 0.2s",
                  }}
                />
              </button>

              {/* Dropdown Menu */}
              <AnimatePresence>
                {filterOpen && (
                  <motion.div
                    initial={{ opacity: 0, y: 10, scale: 0.95 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: 10, scale: 0.95 }}
                    transition={{ duration: 0.2, ease: "easeOut" }}
                    style={{
                      position: "absolute",
                      top: "calc(100% + 10px)",
                      right: 0,
                      width: 160,
                      background: "white",
                      borderRadius: 18,
                      padding: 8,
                      boxShadow: "0 10px 25px rgba(0,0,0,0.15)",
                      zIndex: 100,
                    }}
                  >
                    {[
                      { id: "pending", label: "Pending", bg: "#ff8c8c" },
                      { id: "inprogress", label: "In Progress", bg: "#80bfff" },
                      { id: "resolved", label: "Resolved", bg: "#8ce68c" },
                    ].map((item) => {
                      const isActive = activeFilters.includes(item.id);
                      return (
                        <button
                          key={item.id}
                          onClick={() => {
                            setActiveFilters((prev) =>
                              isActive
                                ? prev.filter((f) => f !== item.id)
                                : [...prev, item.id],
                            );
                          }}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: 10,
                            width: "100%",
                            padding: "10px 12px",
                            borderRadius: 12,
                            background: isActive ? "#F0F4ED" : "transparent",
                            border: "none",
                            cursor: "pointer",
                            marginBottom: 4,
                            transition: "background 0.2s",
                          }}
                        >
                          <div
                            style={{
                              width: 14,
                              height: 14,
                              borderRadius: 4,
                              background: isActive ? item.bg : "#eee",
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "center",
                              transition: "background 0.2s",
                            }}
                          >
                            {isActive && (
                              <div
                                style={{
                                  width: 6,
                                  height: 6,
                                  borderRadius: "50%",
                                  background: "white",
                                }}
                              />
                            )}
                          </div>
                          <span
                            style={{
                              fontSize: 12,
                              fontWeight: 700,
                              color: isActive ? "#4A5E36" : "#888",
                            }}
                          >
                            {item.label}
                          </span>
                        </button>
                      );
                    })}
                  </motion.div>
                )}
              </AnimatePresence>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { AnimatePresence, motion } from "framer-motion";
import {
  X,
  Landmark,
  MapPinned,
  Calendar,
  FileText,
  ChevronDown,
  Navigation,
  Image,
  ShieldAlert,
  Wrench,
  Trash2,
  Dog,
  Construction,
  TreePine,
  CarFront,
  ClipboardList,
} from "lucide-react";

const ICON_MAP = {
  ShieldAlert,
  Wrench,
  Trash2,
  Dog,
  Construction,
  TreePine,
  CarFront,
  ClipboardList,
};

export function MapPopupContent({
  selectedReport,
  popupGeo,
  closePopup,
  STATUS_BG,
  STATUS_COLORS,
  descExpanded,
  setDescExpanded,
  setPhotoModalOpen,
  popupContentRef,
}) {
  return (
    <div ref={popupContentRef} style={{ width: 260, padding: "4px 0 2px" }}>
      {/* Header */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          marginBottom: 10,
        }}
      >
        <div
          style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            background: "#e8f4e0",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          {(() => {
            const DynIcon = ICON_MAP[selectedReport.icon];
            return DynIcon ? (
              <DynIcon size={18} color="#2d8119" />
            ) : (
              <ClipboardList size={18} color="#2d8119" />
            );
          })()}
        </div>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              fontWeight: 800,
              fontSize: 13,
              color: "#1a1108",
              lineHeight: 1.2,
              marginBottom: 3,
            }}
          >
            {selectedReport.title}
          </div>
          <span
            style={{
              fontSize: 9,
              fontWeight: 700,
              padding: "2px 8px",
              borderRadius: 20,
              background: STATUS_BG[selectedReport.status],
              color: STATUS_COLORS[selectedReport.status],
            }}
          >
            {selectedReport.statusLabel}
          </span>
        </div>
        {/* Custom close button */}
        <button
          onClick={closePopup}
          style={{
            width: 24,
            height: 24,
            borderRadius: "50%",
            background: "#f0f0f0",
            border: "none",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
            alignSelf: "flex-start",
            marginTop: -10,
          }}
        >
          <X size={13} color="#555" />
        </button>
      </div>

      {/* Details */}
      <div
        style={{
