      style={{
        position: "absolute",
        inset: 0,
        background: "#F9FDF7",
        zIndex: 10000,
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
      }}
    >
      {/* Header */}
      <div
        style={{
          padding: "16px 20px",
          paddingTop: "calc(16px + env(safe-area-inset-top, 0px))",
          background: "white",
          display: "flex",
          alignItems: "center",
          gap: 12,
          borderBottom: "1px solid #E8EBE5",
          boxShadow: "0 1px 8px rgba(0,0,0,0.04)",
          zIndex: 10,
        }}
      >
        <button
          onClick={onBack}
          style={{
            background: "#f5f0ed",
            border: "none",
            cursor: "pointer",
            padding: "8px",
            borderRadius: "50%",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          <ChevronLeft size={20} strokeWidth={2.5} color="#1A330B" />
        </button>
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              fontSize: 11,
              fontWeight: 700,
              color: "#7B936B",
              textTransform: "uppercase",
              letterSpacing: 0.8,
              marginBottom: 2,
            }}
          >
            Report Details
          </div>
          <h1
            style={{
              fontSize: 15,
              fontWeight: 800,
              color: "#1a1108",
              margin: 0,
              overflow: "hidden",
              textOverflow: "ellipsis",
              whiteSpace: "nowrap",
              display: "flex",
              alignItems: "center",
            }}
          >
            <CategoryIcon
              size={16}
              color="#3F6F23"
              style={{ marginRight: 6, flexShrink: 0 }}
            />
            <span
              style={{
                overflow: "hidden",
                textOverflow: "ellipsis",
                whiteSpace: "nowrap",
              }}
            >
              {selectedCategory}
            </span>
          </h1>
        </div>
        <div
          style={{
            background: "#F2F7EF",
            color: "#3F6F23",
            fontSize: 11,
            fontWeight: 800,
            padding: "4px 10px",
            borderRadius: 20,
            letterSpacing: 0.3,
            flexShrink: 0,
          }}
        >
          Step 2
        </div>
      </div>

      {/* Scrollable body (Location, Photo, Description) */}
      <div
        className="hide-scroll"
        style={{
          flex: 1,
          minHeight: 0,
          overflowY: "auto",
          WebkitOverflowScrolling: "touch",
          padding: "12px 16px 0",
          paddingBottom: 100,
          display: "flex",
          flexDirection: "column",
          gap: 12,
        }}
      >
        <LocationCard
          coords={coords}
          locStatus={locStatus}
          location={location}
          errors={errors}
          addressLine1={addressLine1}
          addressLine2={addressLine2}
          barangayOpen={barangayOpen}
          barangayMatches={barangayMatches}
          onOpenMap={onOpenMap}
          onAddressLine1Change={onAddressLine1Change}
          onAddressLine2Change={(val) => {
            onAddressLine2Change(val);
            setBarangayOpen(true);
            if (val.trim())
              setErrors((e) => ({ ...e, addressLine2: undefined }));
          }}
          onBarangayFocus={() => setBarangayOpen(true)}
          onBarangayBlur={() => setTimeout(() => setBarangayOpen(false), 160)}
          onBarangaySelect={(b) => {
            onAddressLine2Change(b);
            setBarangayOpen(false);
            setErrors((e) => ({ ...e, addressLine2: undefined }));
          }}
        />

        <PhotoCard
          fileRef={fileRef}
          photoPreviews={photoPreviews}
          onRemove={onPhotoRemove}
          onChange={onPhotoChange}
        />

        <DescriptionCard
          description={description}
          errors={errors}
          onChange={(val) => {
            onDescriptionChange(val);
            if (val.trim())
              setErrors((e) => ({ ...e, description: undefined }));
          }}
        />
      </div>

      {/* Fixed Submit Button */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          padding: "12px 20px",
          paddingBottom: "calc(12px + env(safe-area-inset-bottom, 0px))",
          background:
            "linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(255,255,255,1) 30%)",
        }}
      >
        <motion.button
          onClick={onSubmit}
          disabled={isSubmitting}
          style={{
            width: "100%",
            padding: "15px 16px",
            borderRadius: 30,
            background: isSubmitting
              ? "#A8C29D"
              : "linear-gradient(135deg, #4aaa1f 0%, #3F6F23 100%)",
            color: "white",
            border: "none",
            fontSize: 15,
            fontWeight: 600,
            cursor: isSubmitting ? "not-allowed" : "pointer",
            boxShadow: isSubmitting
              ? "none"
              : "0 4px 20px rgba(63, 111, 35, 0.4)",
            letterSpacing: 0.3,
            transition: "all 0.2s",
          }}
        >
          {isSubmitting ? "Sinisave…" : "Submit Report"}
        </motion.button>
      </div>
    </motion.div>
  );
}

import { reverseGeocode } from "./reportConstants";
import { useState, useRef, useEffect } from "react";
import { motion } from "framer-motion";
import { MapView } from "./MapView";
import { CenterPin } from "./CenterPin";
import { BackButton, RecenterButton } from "./MapActionButtons";
import { LocationBottomSheet } from "./LocationBottomSheet";

export default function Step3MapPicker({
  tempCoords,
  location,
  onBack,
  onTempCoordsChange,
  onConfirm,
  onRecenter,
}) {
  const mapRef = useRef(null);
  const [localAddress, setLocalAddress] = useState(
    location || "Drag the map to select a location",
  );
  const [isFetchingAddress, setIsFetchingAddress] = useState(false);
  const [userLocation, setUserLocation] = useState(null);
  const [isTransitioning, setIsTransitioning] = useState(true);

  useEffect(() => {
    const timer = setTimeout(() => setIsTransitioning(false), 200);
    return () => clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          setUserLocation({
            lat: pos.coords.latitude,
            lng: pos.coords.longitude,
          });
        },
        () => {},
        { enableHighAccuracy: true },
      );
    }
  }, []);

  const handleRecenterLocal = () => {
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const lat = pos.coords.latitude;
          const lng = pos.coords.longitude;
          setUserLocation({ lat, lng });
          mapRef.current?.flyTo({
            center: [lng, lat],
            zoom: 16.5,
            duration: 800,
          });
          onTempCoordsChange({ lat, lng });
        },
        () => {},
        { enableHighAccuracy: true },
      );
    }
  };

  const handleMoveEnd = async (e) => {
    const lat = e.viewState.latitude;
    const lng = e.viewState.longitude;
    setIsFetchingAddress(true);
    try {
      const { address } = await reverseGeocode(lat, lng);
      setLocalAddress(address);
    } catch {
      setLocalAddress(`${lat.toFixed(5)}, ${lng.toFixed(5)}`);
    }
    setIsFetchingAddress(false);
  };

  return (
    <motion.div
      initial={{ y: "100%" }}
      animate={{ y: 0 }}
      exit={{ y: "100%" }}
      transition={{ type: "tween", duration: 0.35, ease: [0.32, 0.72, 0, 1] }}
      style={{
        position: "absolute",
        inset: 0,
        zIndex: 10001,
        display: "flex",
        flexDirection: "column",
        background: "#f0ece8",
      }}
    >
      {/* Full-screen map */}
      <div style={{ flex: 1, position: "relative", background: "#f0ece8" }}>
        <MapView
          isTransitioning={isTransitioning}
          mapRef={mapRef}
          tempCoords={tempCoords}
          onTempCoordsChange={onTempCoordsChange}
          handleMoveEnd={handleMoveEnd}
          userLocation={userLocation}
        />

        {/* Fixed center pin */}
        <CenterPin />

        {/* Action buttons */}
        <BackButton onClick={onBack} />
        <RecenterButton onClick={handleRecenterLocal} />
      </div>

      {/* Bottom sheet */}
      <LocationBottomSheet
        isFetchingAddress={isFetchingAddress}
        localAddress={localAddress}
        onConfirm={onConfirm}
      />
    </motion.div>
  );
}

import { CheckCircle } from "lucide-react";
import { motion } from "framer-motion";
import { useEffect } from "react";

export default function Step4Success({ onClose }) {
  useEffect(() => {
    const timer = setTimeout(onClose, 3500);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.95 }}
      transition={{ duration: 0.4, ease: "easeOut" }}
      style={{
        position: "absolute",
        inset: 0,
        background: "#F9FDF7",
        zIndex: 10000,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        padding: 24,
      }}
    >
      <motion.div
        initial={{ scale: 0, rotate: -45 }}
        animate={{ scale: 1, rotate: 0 }}
        transition={{
          type: "spring",
          stiffness: 260,
          damping: 20,
          delay: 0.1,
        }}
        style={{
          width: 80,
          height: 80,
          borderRadius: "50%",
          background: "#E8F5E9",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginBottom: 24,
        }}
      >
        <motion.div
          initial={{ pathLength: 0, opacity: 0 }}
          animate={{ pathLength: 1, opacity: 1 }}
          transition={{ duration: 0.5, delay: 0.3 }}
        >
          <CheckCircle size={40} color="#3F6F23" />
        </motion.div>
      </motion.div>

      <motion.h2
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.4, ease: "easeOut" }}
        style={{
          fontSize: 22,
          fontWeight: 800,
          color: "#1a1108",
          marginBottom: 12,
          textAlign: "center",
        }}
      >
        Report Submitted!
      </motion.h2>

      <motion.p
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.5, ease: "easeOut" }}
        style={{
          fontSize: 14,
          color: "#7B936B",
          textAlign: "center",
          lineHeight: 1.5,
          marginBottom: 32,
          maxWidth: 280,
        }}
      >
        Thank you for helping our community. Your report has been submitted
        successfully and is now being reviewed.
      </motion.p>

      <motion.button
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, delay: 0.6, ease: "easeOut" }}
        whileHover={{ scale: 1.02 }}
        whileTap={{ scale: 0.98 }}
        onClick={onClose}
        style={{
          width: "100%",
          maxWidth: 300,
          padding: "16px",
          borderRadius: 30,
          background: "linear-gradient(135deg, #4aaa1f 0%, #3F6F23 100%)",
          color: "white",
          fontWeight: 800,
          fontSize: 15,
          border: "none",
          cursor: "pointer",
          boxShadow: "0 4px 15px rgba(63, 111, 35, 0.3)",
          transition: "transform 0.1s",
        }}
      >
        Done
      </motion.button>
    </motion.div>
  );
}

